const tasks=[{title:'Update onboarding screens',name:'Maya',date:'Sep 11',avatar:47,badge:'High',kind:'high',done:false,detail:'Update the onboarding designs for the agreed three-step flow. Designs are due before Friday’s handoff.'},{title:'Finalize welcome copy',name:'Alex',date:'Sep 11',avatar:12,badge:'In progress',kind:'progress',done:false,detail:'Finalize the welcome copy for the onboarding flow before Friday’s handoff.'},{title:'Share meeting notes',name:'Sam',date:'Sep 10',avatar:33,badge:'Done',kind:'progress',done:true,detail:'Share the Product sync meeting notes with the team.'}];
const icons={Meetings:'<rect x="3" y="5" width="18" height="17" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',Notes:'<path d="M14 2H5v20h15V8l-6-6Z M14 2v7h6 M8 13h8m-8 4h6"/>',AI:'<path d="M11 3c0 6-3 9-8 10 5 1 8 4 8 9 1-5 4-8 9-9-5-1-8-4-9-10ZM20 2v5m-2.5-2.5h5"/>',Tasks:'<circle cx="12" cy="12" r="10"/><path d="m7 12 3 3 7-7"/>',Profile:'<circle cx="12" cy="6" r="4"/><path d="M3 22v-3c0-8 18-8 18 0v3"/>'};
function render(){document.querySelector('#tasks').innerHTML=tasks.map((t,i)=>`<article class="task ${t.done?'done':''}"><button class="check" role="checkbox" aria-checked="${t.done}" aria-label="Complete ${t.title}" data-check="${i}"><span>${t.done?'<svg viewBox="0 0 24 24"><path d="m5 12 5 5 10-11" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>':''}</span></button><button class="task-text" data-task="${i}"><h3>${t.title}</h3><p><img src="https://i.pravatar.cc/80?img=${t.avatar}" alt="">${t.name} · ${t.date}</p></button><span class="badge ${t.kind}">${t.done?'Done':t.badge==='Done'?'To do':t.badge}</span></article>`).join('');document.querySelector('#count').textContent=`${tasks.filter(t=>t.done).length} of 3 done`;}
function openDialog(title,content){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').replaceChildren();if(typeof content==='string'){const p=document.createElement('p');p.textContent=content;document.querySelector('#dialog-body').append(p);}else document.querySelector('#dialog-body').append(content);document.querySelector('#dialog').showModal();}
document.querySelector('#tasks').addEventListener('click',e=>{const check=e.target.closest('[data-check]');if(check){tasks[check.dataset.check].done=!tasks[check.dataset.check].done;render();document.querySelector(`[data-check="${check.dataset.check}"]`).focus();return;}const button=e.target.closest('[data-task]');if(button){const t=tasks[button.dataset.task];openDialog(t.title,`${t.name} · Due ${t.date}\n${t.detail}`);}});
document.querySelector('#close').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
document.querySelectorAll('.participants').forEach(b=>b.onclick=()=>openDialog('Participants','Maya, Alex, Sam, and two other participants. The other participants’ names are not included in this meeting overview.'));
document.querySelector('#more').onclick=()=>{const b=document.createElement('button');b.className='menu-action';b.textContent='Download meeting notes';b.onclick=()=>{const text='Product sync — Sep 10, 2026\n\n'+document.querySelector('.summary p').textContent+'\n\nKey decisions\nSimplify onboarding: Use a three-step flow for new users.\nKeep the release focused: Move dashboard changes to the next sprint.\n\nAction items\n'+tasks.map(t=>`${t.done?'[x]':'[ ]'} ${t.title} — ${t.name}, ${t.date}`).join('\n');const u=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=u;a.download='product-sync-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);document.querySelector('#dialog').close();};openDialog('Meeting options',b);};
document.querySelector('#composer').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#question');const q=input.value.trim();if(!q){input.focus();return;}const lower=q.toLowerCase();let answer='The meeting overview does not contain that information. You can ask about the summary, decisions, owners, or deadlines.';if(/who|owner|assign|task|action/.test(lower))answer=tasks.map(t=>`${t.name}: ${t.title}, due ${t.date}${t.done?' (done)':''}.`).join(' ');else if(/when|due|deadline|friday/.test(lower))answer='Updated designs and final copy are due Sep 11, before Friday’s handoff. Sam’s meeting notes were due Sep 10 and are complete.';else if(/decision|scope|release|dashboard|onboarding/.test(lower))answer='The team agreed on a three-step onboarding flow for new users and moved dashboard changes to the next sprint to keep the release focused.';else if(/summary|summari|discuss|meeting/.test(lower))answer=document.querySelector('.summary p').textContent;openDialog('From this meeting',answer);};
document.querySelector('#nav').innerHTML=Object.entries(icons).map(([name,svg])=>`<button class="${name==='Meetings'?'active':''}" ${name==='Meetings'?'aria-current="page"':''} data-tab="${name}"><svg viewBox="0 0 24 24" aria-hidden="true">${svg}</svg><span>${name}</span></button>`).join('');
document.querySelector('#nav').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;const tab=b.dataset.tab;if(tab==='Meetings'){document.querySelector('#main').scrollIntoView({behavior:'smooth'});return;}if(tab==='AI'){document.querySelector('#question').focus();return;}if(tab==='Notes')openDialog('Meeting notes',document.querySelector('.summary p').textContent+' The team agreed to simplify onboarding to three steps and move dashboard changes to the next sprint.');if(tab==='Tasks')openDialog('Meeting tasks',tasks.map(t=>`${t.done?'✓':'○'} ${t.title} — ${t.name} · ${t.date}`).join('\n'));if(tab==='Profile')openDialog('Profile','This meeting preview is not connected to an account.');};render();
